ALTER TABLE public.cms_roles ADD COLUMN system_key text;
ALTER TABLE public.cms_roles ADD CONSTRAINT cms_roles_system_key_unique UNIQUE(system_key);
ALTER TABLE public.cms_roles ADD CONSTRAINT cms_roles_system_key_valid CHECK(system_key IS NULL OR system_key IN ('webbuilder','basic','advanced'));
CREATE OR REPLACE FUNCTION public.cms_default_perms(_key text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT jsonb_build_object('text',true,'images',true,'forms',true,'stats',true,'blocks',_key IN ('webbuilder','advanced'),'translate',_key IN ('webbuilder','advanced'),'activity',_key IN ('webbuilder','advanced'),'pages',_key='webbuilder','settings',_key='webbuilder','backups',_key='webbuilder','users',false,'dns',false,'updates',false,'restore',false) $$;
UPDATE public.cms_roles SET system_key='webbuilder',perms=public.cms_default_perms('webbuilder') WHERE id=(SELECT id FROM public.cms_roles WHERE name='Webbouwer' ORDER BY created_at LIMIT 1);
UPDATE public.cms_roles SET system_key='basic',name='Klant Basis',perms=public.cms_default_perms('basic') WHERE id=(SELECT id FROM public.cms_roles WHERE name='Klant' ORDER BY created_at LIMIT 1);
CREATE OR REPLACE FUNCTION public.has_perm(_user_id uuid,_perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR (_perm NOT IN ('users','dns','updates','restore') AND EXISTS (SELECT 1 FROM public.user_roles ur LEFT JOIN public.cms_roles c ON c.id=ur.cms_role_id WHERE ur.user_id=_user_id AND ur.role='editor' AND COALESCE(((CASE WHEN c.system_key IS NOT NULL THEN public.cms_default_perms(c.system_key) ELSE c.perms END)->>_perm)::boolean,_perm IN ('text','images','forms','stats')))) $$;
CREATE OR REPLACE FUNCTION public.my_perms() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_object_agg(k,public.has_perm(auth.uid(),k)) FROM unnest(ARRAY['text','images','forms','stats','blocks','translate','activity','pages','settings','backups','users','dns','updates','restore']) k $$;
DROP POLICY IF EXISTS "User managers manage role profiles" ON public.cms_roles;
CREATE POLICY "Administrators manage role profiles" ON public.cms_roles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.guard_cms_standard_role() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF TG_OP='INSERT' AND NEW.system_key IS NOT NULL THEN RAISE EXCEPTION 'Standaardrollen worden door de master beheerd'; END IF; IF TG_OP IN ('UPDATE','DELETE') AND OLD.system_key IS NOT NULL THEN RAISE EXCEPTION 'Standaardrollen staan vast; maak een extra rol aan'; END IF; IF TG_OP='UPDATE' AND NEW.system_key IS DISTINCT FROM OLD.system_key THEN RAISE EXCEPTION 'Standaardrollen worden door de master beheerd'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_cms_standard_role BEFORE INSERT OR UPDATE OR DELETE ON public.cms_roles FOR EACH ROW EXECUTE FUNCTION public.guard_cms_standard_role();
CREATE OR REPLACE FUNCTION public.restore_site_backup(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Alleen Administrator kan een back-up terugzetten'; END IF; SELECT data INTO b FROM site_backups WHERE id=_id; IF b IS NULL THEN RAISE EXCEPTION 'Back-up niet gevonden'; END IF;
IF b ? 'custom_pages' THEN
DELETE FROM page_content WHERE path IN (SELECT path FROM custom_pages); DELETE FROM page_seo WHERE path IN (SELECT path FROM custom_pages); DELETE FROM page_settings WHERE path IN (SELECT path FROM custom_pages); DELETE FROM custom_pages WHERE path IS NOT NULL; INSERT INTO custom_pages SELECT * FROM jsonb_populate_recordset(NULL::public.custom_pages,b->'custom_pages');
END IF;
DELETE FROM page_content WHERE path IS NOT NULL; DELETE FROM page_seo WHERE path IS NOT NULL; DELETE FROM page_settings WHERE path IS NOT NULL;
INSERT INTO page_content SELECT * FROM jsonb_populate_recordset(NULL::public.page_content,b->'page_content'); INSERT INTO page_seo SELECT * FROM jsonb_populate_recordset(NULL::public.page_seo,b->'page_seo'); INSERT INTO page_settings SELECT * FROM jsonb_populate_recordset(NULL::public.page_settings,b->'page_settings'); END $$;
REVOKE EXECUTE ON FUNCTION public.cms_default_perms(text),public.guard_cms_standard_role() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.cms_default_perms(text) TO authenticated,service_role;
REVOKE EXECUTE ON FUNCTION public.has_perm(uuid,text),public.my_perms(),public.restore_site_backup(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_perm(uuid,text),public.my_perms(),public.restore_site_backup(uuid) TO authenticated;